NotificationList

function NotificationList({ type }: { type: TabType }) {
  const notifications = useMemo(() => {
    if (type === 'all') return MOCK_NOTIFICATIONS;
    return MOCK_NOTIFICATIONS.filter(n => 
       type === 'orders' ? n.type === 'order' : n.type === 'promo'
    );
  }, [type]);

  if (notifications.length === 0) {
    return (
      <div className="py-24 text-center text-foreground/40">
        <Bell className="mx-auto mb-4 opacity-10" size={48} />
        <p className="text-sm">No {type} notifications yet</p>
      </div>
    );
  }

  return (
    <div className="divide-y divide-foreground/10">
      {notifications.map((n) => (
        <div key={n.id} className="flex gap-4 p-5 hover:bg-foreground transition-colors">
          <div className="shrink-0 w-11 h-11 flex items-center justify-center rounded-full bg-foreground text-background">
            {n.type === 'order' ? <ShoppingBag size={20} /> : <Tag size={20} />}
          </div>
          <div className="flex-1">
            <div className="flex justify-between items-start">
              <h3 className="text-[14px] font-semibold tracking-tight">{n.title}</h3>
              <span className="text-[10px] font-medium text-foreground/40 uppercase">{n.timestamp}</span>
            </div>
            <p className="text-[13px] text-foreground/60 mt-1 leading-relaxed">
              {n.message}
            </p>
          </div>
        </div>
      ))}
    </div>
  );
}

const MOCK_NOTIFICATIONS = [
  { id: '1', type: 'order', title: 'Order Shipped', message: 'Your order #FF-2025 has been shipped. Track your shipment now.', timestamp: '2 mins ago' },
  { id: '2', type: 'promo', title: 'Flash Sale Alert', message: 'The Monochrome Collection is now 40% off. Limited time only.', timestamp: '1 hour ago' },
  { id: '3', type: 'order', title: 'Order Delivered', message: 'Order #FF-2023 has been delivered at your doorstep.', timestamp: '2 days ago' },
  { id: '4', type: 'promo', title: 'Exclusive Access', message: 'Early access to our anniversary sale is now open.', timestamp: '3 days ago' },
  { id: '5', type: 'order', title: 'Order Confirmed', message: 'We’ve received your order #FF-2031.', timestamp: '5 days ago' },
  { id: '6', type: 'promo', title: 'Free Shipping', message: 'Enjoy free shipping on all orders this weekend.', timestamp: '1 week ago' },
  { id: '7', type: 'order', title: 'Refund Processed', message: 'Refund for #FF-1980 is complete.', timestamp: '2 weeks ago' },
];